// Same arithmetic as the application's prediction engine, kept
// deliberately simple so it can be read alongside it.
const AIRPORT = { latitude: 53.3537, longitude: -2.275 };
const VECTORING = 1.15;
const TAXI_MINUTES = 6;
const FINAL_APPROACH_KM = 25;
const FINAL_APPROACH_MINUTES = 8;

const config = $('Configuration').first().json;
const snapshot = $input.first().json;
const wanted = String(config.callsign).trim().toUpperCase();

function haversineKm(a, b) {
  const rad = (d) => (d * Math.PI) / 180;
  const dLat = rad(b.latitude - a.latitude);
  const dLon = rad(b.longitude - a.longitude);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.latitude)) * Math.cos(rad(b.latitude)) * Math.sin(dLon / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
}

const aircraft = (snapshot.aircraft || []).find(
  (entry) => String(entry.callsign).trim().toUpperCase() === wanted,
);

if (!aircraft) {
  return [{ json: { found: false, callsign: wanted, generatedAt: snapshot.generatedAt } }];
}

const distanceKm = haversineKm(aircraft, AIRPORT);
const observedAt = aircraft.lastContact * 1000;

let minutesRemaining;
if (aircraft.onGround) {
  minutesRemaining = distanceKm <= 8 ? TAXI_MINUTES : null;
} else if (aircraft.verticalRateMps > 4 && distanceKm < 90) {
  // Climbing away from the airport: this is the outbound leg, not an arrival.
  minutesRemaining = null;
} else if (distanceKm <= FINAL_APPROACH_KM) {
  minutesRemaining = FINAL_APPROACH_MINUTES + TAXI_MINUTES;
} else if ((aircraft.groundSpeedMps || 0) >= 40) {
  const speedKph = (aircraft.groundSpeedMps * 3600) / 1000;
  minutesRemaining = Math.round(
    ((distanceKm * VECTORING) / speedKph) * 60 + FINAL_APPROACH_MINUTES + TAXI_MINUTES,
  );
} else {
  minutesRemaining = null;
}

return [
  {
    json: {
      found: true,
      callsign: wanted,
      distanceKm: Math.round(distanceKm),
      onGround: aircraft.onGround,
      minutesRemaining,
      estimatedOnStand:
        minutesRemaining === null ? null : new Date(observedAt + minutesRemaining * 60000).toISOString(),
      observedAt: new Date(observedAt).toISOString(),
      generatedAt: snapshot.generatedAt,
    },
  },
];

// Compare with the previous run and only pass on meaningful moves.
const config = $('Configuration').first().json;
const current = $input.first().json;
const previous = $getWorkflowStaticData('global');

if (!current.found || current.estimatedOnStand === null) {
  return [{ json: { ...current, changed: false, reason: 'No usable position for this callsign.' } }];
}

const estimate = Date.parse(current.estimatedOnStand);
const last = previous.lastEstimate ? Date.parse(previous.lastEstimate) : null;
previous.lastEstimate = current.estimatedOnStand;

if (last === null) {
  return [{ json: { ...current, changed: false, reason: 'First observation recorded.' } }];
}

const deltaMinutes = Math.round((estimate - last) / 60000);
const changed = Math.abs(deltaMinutes) >= Number(config.thresholdMinutes);

return [
  {
    json: {
      ...current,
      changed,
      deltaMinutes,
      reason: changed
        ? `Estimated arrival moved ${Math.abs(deltaMinutes)} minutes ${deltaMinutes > 0 ? 'later' : 'earlier'}.`
        : 'Nothing meaningful changed.',
    },
  },
];

// Emit the event. Delivering it — desktop notification, webhook, message —
// is deliberately left to you: every service that would deliver it for you
// costs money, and SetoffIQ is built to cost nothing.
console.log('SetoffIQ change:', $input.first().json.reason);
return $input.all();
